<?php require __DIR__ . '/auth.php'; $screen = (string) ($_GET['screen'] ?? ''); $display = display_by_id($screen); if ($display === null) { http_response_code(400); exit('Unbekanntes Display.'); } ?>
<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Signage Monitor</title><style>html,body{margin:0;width:100%;height:100%;background:#000;overflow:hidden}#content{position:fixed;left:0;top:0;width:100vw;height:100vh}#content img,#content video{width:100%;height:100%;object-fit:contain}#content.orientation-180{transform:rotate(180deg)}#content.orientation-90,#content.orientation-270{width:100vh;height:100vw;left:50vw;top:50vh;transform:translate(-50%,-50%) rotate(90deg)}#content.orientation-270{transform:translate(-50%,-50%) rotate(270deg)}</style><body><div id="content" class="orientation-<?= (int) $display['orientation'] ?>"><img id="signageBild" src="standard_<?= h($screen) ?>.jpg" alt="Signage"><video id="signageVideo" hidden muted autoplay loop playsinline></video></div><script>
const playlistUrl = <?= json_encode('playlist.php?screen=' . rawurlencode($screen)) ?>;
let currentImage = '';
async function aktualisiereDisplay(){try{const response=await fetch(playlistUrl,{cache:'no-store'});if(!response.ok)throw new Error();const data=await response.json();if(data.image!==currentImage){currentImage=data.image;const image=document.getElementById('signageBild'),video=document.getElementById('signageVideo'),url=data.image+(data.image.includes('?')?'&':'?')+'v='+Date.now();if(data.type==='video'){image.hidden=true;video.hidden=false;video.src=url;video.play().catch(()=>{});}else{video.pause();video.hidden=true;image.hidden=false;image.src=url;}}}catch(e){console.warn('Playlist nicht erreichbar');}}
aktualisiereDisplay(); setInterval(aktualisiereDisplay,60000);
</script></body></html>
